/* SHOPPER 9.0 — private-family PWA, cookie sessions + collaborative baskets.
   No tracking, payments, live retailer integration or external API calls. */
'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'—':new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(v)/100);
const numMoney=v=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(v)||0);
const friendly=d=>{if(!d)return '—';const dt=new Date(d);return Number.isNaN(+dt)?String(d):dt.toLocaleString('es-ES',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});};
const TODAY=()=>new Date().toISOString().slice(0,10);
const tomorrow=()=>{const d=new Date(Date.now()+86400000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
let sessionReady=false, csrf='',config=null, basketStream=null,streamBasketId=null;
const inviteFromUrl=new URL(location.href).searchParams.get('invite');
let prefillInvite=inviteFromUrl||'';
let state=null,view='home',basketId=null,basketDetail=null,compareData=null,placeId=null,searchProduct='',searchStore='',geo=null,selectedBasketCatalog=null,invitation=null,econ=null,barcodeStream=null,selectedStoreId=null,shelfData=null;
const SECTION={home:'Mi día',baskets:'Mis cestas',circle:'Mi círculo',pantry:'Despensa',catalog:'Productos',stores:'Mis supermercados',live:'SHOPPER Live',community:'Foodpedia',orders:'Mis encargos',shopper:'Ser shopper',watch:'Seguimientos',history:'Compras reales',business:'Rentabilidad',account:'Ajustes'};
function toast(message,error=false){const x=$('toast');x.textContent=message;x.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>x.className='',4900)}
function formdata(el){return Object.fromEntries(new FormData(el).entries())}
async function api(path,method='GET',payload){
 const headers={'Accept':'application/json'};
 if(payload!==undefined)headers['Content-Type']='application/json';
 if(!['GET','HEAD'].includes(method)&&csrf)headers['X-Shopper-CSRF']=csrf;
 const res=await fetch(path,{method,headers,credentials:'same-origin',body:payload===undefined?undefined:JSON.stringify(payload),cache:'no-store'});
 let parsed;try{parsed=await res.json()}catch{parsed={detail:'No llegó una respuesta válida'}}
 if(!res.ok){
  if(res.status===401&&sessionReady){sessionReady=false;csrf='';showAuth()}
  let message=parsed.detail||parsed.message||'Error de comunicación';
  if(Array.isArray(message))message=message.map(x=>x.msg).join('; ');
  throw Error(message)
 }
 return parsed
}
function closeBasketStream(){if(basketStream){basketStream.close();basketStream=null;streamBasketId=null}}
function showAuth(){closeBasketStream();$('authScreen').classList.remove('hidden');$('appShell').classList.add('hidden');state=null;view='home'}
async function authLogin(username,password){const r=await api('/api/auth/login','POST',{username,password});csrf=r.csrf;sessionReady=true;await refresh(false);toast('Sesión iniciada de forma privada');applyIncomingInvite()}
function applyIncomingInvite(){if(prefillInvite&&sessionReady){
 goto('baskets');const x=document.querySelector('#redeemInvitation input[name="code"]');if(x)x.value=prefillInvite;
 toast('Invitación recibida: revisa y pulsa Aceptar');
 prefillInvite='';if(location.protocol==='http:'||location.protocol==='https:')window.history.replaceState({},'',location.pathname);
}}
async function refresh(keep=true){
 if(!sessionReady){showAuth();return}
 state=await api('/api/bootstrap');$('authScreen').classList.add('hidden');$('appShell').classList.remove('hidden');
 $('userPill').innerHTML=`<span class="avatar">${esc(state.me.display_name[0].toUpperCase())}</span><span>${esc(state.me.display_name)}</span>`;
 if(!keep||!state.baskets.some(x=>x.id===basketId))basketId=state.baskets.find(x=>x.kind==='actual'&&x.owner_id===state.me.id)?.id||state.baskets[0]?.id||null;
 if(!state.places.some(x=>x.id===placeId))placeId=state.places[0]?.id||null;
 if(!state.baskets.some(x=>x.id===selectedBasketCatalog))selectedBasketCatalog=basketId;
 if(view==='baskets'&&basketId){try{basketDetail=await api('/api/baskets/'+basketId)}catch{basketDetail=null;compareData=null}}
 render();maintainBasketStream();
}
function goto(where){view=SECTION[where]?where:'home';compareData=null;if(view==='circle'&&sessionReady){refresh().catch(e=>toast(e.message,true))}else{render();maintainBasketStream()}window.scrollTo({top:0,behavior:'instant'})}
function maintainBasketStream(){
 if(!sessionReady||view!=='baskets'||!basketId){closeBasketStream();return}
 if(streamBasketId===basketId&&basketStream)return;
 closeBasketStream();
 if(!('EventSource' in window))return;
 basketStream=new EventSource(`/api/baskets/${basketId}/events`,{withCredentials:true});streamBasketId=basketId;
 basketStream.addEventListener('updated',async()=>{
  if(document.visibilityState!=='visible')return;
  const a=document.activeElement;
  if(a&&['INPUT','TEXTAREA','SELECT'].includes(a.tagName))return;
  try{await refresh()}catch(e){console.warn('Cesta pendiente de sincronizar',e.message)}
 });
 basketStream.addEventListener('revoked',()=>{closeBasketStream();refresh().catch(()=>showAuth())});
}
function render(){if(!state)return;$('breadcrumb').innerHTML=esc(SECTION[view]).toUpperCase()+' <small>/ CÍRCULO PRIVADO</small>';
 document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===view));
 const r={home:renderHome,baskets:renderBaskets,circle:renderCircle,pantry:renderPantry,catalog:renderCatalog,stores:renderStores,live:renderLive,community:renderCommunity,orders:renderOrders,shopper:renderShopper,watch:renderWatch,history:renderHistory,business:renderBusiness,account:renderAccount};
 $('content').innerHTML=r[view]();}
const head=(tag,title,description,right='')=>`<div class="page-head"><div><div class="eyebrow">${esc(tag)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${right}</div>`;
const pill=(s,kind='')=>`<span class="pill ${kind}">${esc(s)}</span>`;
const shortEmpty=message=>`<div class="empty">${esc(message)}</div>`;
const opts=(items,selected,fmt,id='id')=>items.map(x=>`<option value="${esc(x[id])}" ${String(x[id])===String(selected)?'selected':''}>${esc(fmt(x))}</option>`).join('');
const productSelect=(selected,empty='Selecciona producto')=>`<option value="">${esc(empty)}</option>`+opts(state.products,selected,x=>x.name);
const storeSelect=(selected)=>`<option value="">Selecciona tienda</option>`+opts(state.stores,selected,x=>x.name);
const placeSelect=(selected)=>`<option value="">Ningún lugar</option>`+opts(state.places,selected,x=>x.name);
const basketSelect=(selected)=>opts(state.baskets,selected,x=>x.title+(x.my_role==='reader'?' · lectura':''));
const recentPrices=()=>state.prices.filter(p=>new Date(p.observed_at)>new Date(Date.now()-14*86400000));
function getBasketAlerts(){if(!basketDetail)return[];return basketDetail.items.filter(i=>state.pantry.some(p=>p.state==='active'&&p.product_id===i.product_id));}
function soonPantry(){return state.pantry.filter(p=>p.state==='active'&&p.expires_on&&p.expires_on<=new Date(Date.now()+4*86400000).toISOString().slice(0,10));}
const activePantry=()=>state.pantry.filter(x=>x.state==='active');
const fmtQty=v=>Number(v).toLocaleString('es-ES',{maximumFractionDigits:2});
function renderHome(){
 const due=soonPantry(), tasks=state.family_tasks||[], mine=tasks.filter(t=>t.status==='open'||t.status==='accepted');
 const first=state.baskets.find(b=>b.kind==='actual'&&b.owner_id===state.me.id);
 return `<div class="home-hero"><div class="hero-kicker">TU COMPRA, TU GENTE, TU TIEMPO</div>
   <h1>Que la compra no<br>te robe la vida<span>.</span></h1>
   <p>Una cesta compartida, las tiendas que conoces y todo tu círculo coordinado. Compra solo lo que necesitas.</p>
   <div class="hero-actions"><button data-nav="baskets" class="btn btn-lime">Abrir mi cesta <span>↗</span></button>
   <button data-nav="circle" class="btn btn-hero-outline">Mi círculo familiar</button></div>
   <div class="hero-foot"><span>✦ SIN SUSCRIPCIÓN</span><span>✦ SIN PEDIDOS FICTICIOS</span><span>✦ TUS DATOS, EN PRIVADO</span></div></div>
 <div class="home-shortcuts"><button data-nav="baskets" class="home-shortcut"><span>🛒</span><strong>Cestas</strong><small>${state.baskets.length} guardadas</small></button>
 <button data-nav="circle" class="home-shortcut"><span>🤝</span><strong>Mi círculo</strong><small>${mine.length} recados abiertos</small></button>
 <button data-nav="pantry" class="home-shortcut"><span>🥕</span><strong>Despensa</strong><small>${due.length} por revisar</small></button>
 <button data-nav="stores" class="home-shortcut"><span>📍</span><strong>Mis tiendas</strong><small>${state.places.length} lugares</small></button></div>
 <div class="section-title"><div><div class="eyebrow">PARA HOY</div><h2>Tu vida organizada</h2></div>${pill('Beta familiar privada')}</div>
 <div class="grid two"><div class="panel calm-panel"><div class="row top"><h3>La cesta que siempre está contigo</h3><span class="feature-glyph">🧺</span></div>
  <p>Escribe cualquier producto en segundos. Comparte con tu familia y ve cómo se actualiza al comprar.</p>
  <div class="feature-meta">${first?.item_count||0} artículos en «Actual»</div><button class="btn btn-primary" data-nav="baskets">Preparar compra →</button></div>
 <div class="panel"><div class="row top"><h3>Recados entre personas de confianza</h3><span class="feature-glyph">🤝</span></div>
 <p>Deja preparada la cesta para tu padre o coordina una compra para una persona mayor, sin confundirlo con una reserva en tienda.</p>
 <div class="feature-meta">${mine.length} recados abiertos o aceptados</div><button class="btn btn-secondary" data-nav="circle">Organizar mi círculo →</button></div></div>
 <div class="grid two" style="margin-top:15px"><div class="panel"><h3>Antes de volver a comprar…</h3>
 ${due.length?due.slice(0,4).map(i=>`<div class="srow"><div><strong>⏳ ${esc(i.product_name||i.custom_name)}</strong><small>Fecha anotada: ${esc(i.expires_on)}</small></div></div>`).join(''):'<div class="hint">Comprueba tu despensa y evita duplicados. Puedes registrar lo que consumes y lo que descartas.</div>'}
 <button class="btn btn-small btn-soft" data-nav="pantry" style="margin-top:13px">Revisar despensa</button></div>
 <div class="panel"><h3>Ofertas: datos antes que promesas</h3><p>Consulta las observaciones de tu comunidad por tienda, fecha y fuente. Nunca tratamos una aportación como stock garantizado.</p>
 <div class="event-list"><span>${recentPrices().length} precios observados recientes</span><span>${state.reports.length} avisos Live</span><span>0 conexiones con cajas</span></div>
 <button class="btn btn-small btn-soft" data-nav="stores" style="margin-top:13px">Explorar establecimientos</button></div></div>`;
}
function renderBaskets(){const arr=state.baskets;const current=arr.find(x=>x.id===basketId);const detail=basketDetail;const b=current;
 return head('TU ESPACIO PERSONAL','Mis cestas','Crea tantas como quieras. Una cesta Actual rápida, otras recurrentes, para fiestas, familias o antojos, con edición mediante invitaciones.')+
 `<div class="workbench"><div class="stack"><div class="panel"><div class="row"><h3>Biblioteca de cestas</h3>${pill(String(arr.length)+' cestas')}</div>
 <div class="stack" style="margin-top:15px">${arr.map(x=>`<button class="choice ${x.id===basketId?'active':''}" data-open-basket="${x.id}"><span class="emoji">${{actual:'🛒',evento:'🎉',semanal:'📆',mensual:'🗓️',ocasional:'🍫'}[x.kind]||'▤'}</span><span style="flex:1"><strong>${esc(x.title)}</strong><small>${esc(x.kind)} · ${x.item_count} referencias · ${esc(x.owner_name)}</small></span><span>›</span></button>`).join('')}</div>
 <div class="divider"></div><h3>Nueva cesta</h3><form id="createBasket" class="form"><label>Nombre<input name="title" required maxlength="90" placeholder="Cena con amigos, compra semanal…"></label><label>Tipo<select name="kind"><option value="ocasional">Ocasional</option><option value="evento">Evento / fiesta</option><option value="semanal">Semanal</option><option value="mensual">Mensual</option></select></label><button class="btn btn-primary">Crear cesta +</button></form></div>
 <div class="panel"><h3>Colaborar de verdad</h3><p>Comparte un código de un solo uso con otra cuenta y acepta invitaciones. Los permisos se comprueban en el servidor.</p><form id="redeemInvitation" class="form"><label>Código de invitación<input name="code" required minlength="15" placeholder="Pega aquí un código recibido"></label><button class="btn btn-secondary">Aceptar invitación</button></form>
 <div class="divider"></div><h3>Amigos</h3><div class="stack">${state.friends.length?state.friends.map(f=>`<div class="srow"><strong>👤 ${esc(f.display_name)}</strong><button data-action="removeFriend" data-uid="${f.id}" class="btn btn-small btn-danger">Desconectar</button></div>`).join(''):shortEmpty('Todavía no has conectado con otras personas.')}</div><button data-action="friendInvite" class="btn btn-small btn-soft" style="margin-top:12px">Crear invitación de amistad</button>
 ${invitation&&invitation.kind==='friend'?showInvite(invitation):''}</div></div>
 <div class="stack">${b&&detail?renderBasketDetail(b,detail):'<div class="panel">Selecciona una cesta.</div>'}</div></div>`;}
function showInvite(i){return `<div class="invite-spot"><strong>Invita sin compartir tu contraseña</strong><p>El enlace sirve una sola vez y caduca en 7 días.</p>
 <div class="codebox">${esc(i.code)}</div><div class="button-row" style="margin-top:9px">
 <button class="btn btn-small btn-primary" data-action="shareInvite" data-code="${esc(i.code)}">Compartir enlace ↗</button>
 <button class="btn btn-small btn-secondary" data-action="copy" data-code="${esc(i.code)}">Copiar código</button></div></div>`}
function renderBasketDetail(b,detail){
 const canEdit=detail.my_role==='owner'||detail.my_role==='editor';
 const pantryOverlap=getBasketAlerts(),limit=b.budget_cents?money(b.budget_cents):'Sin definir';
 const checked=detail.checked_count||0,all=detail.items.length;
 return `<div class="panel"><div class="row top"><div><div class="eyebrow">CESTA SELECCIONADA</div><h2>${esc(b.title)}</h2><div class="tags">${pill(b.kind)}${pill(detail.my_role==='owner'?'Propietario':detail.my_role)}<span class="live-indicator"><span class="live-dot"></span> Sincronización al instante*</span></div></div>
 <div class="button-row"><button data-action="refreshBasket" class="btn btn-small btn-soft">↻ Actualizar</button><button data-action="duplicateBasket" class="btn btn-small btn-secondary">Duplicar</button>${b.kind!=='actual'?'<button data-action="copyActual" class="btn btn-small btn-secondary">+ A mi cesta Actual</button>':''}${detail.my_role==='owner'&&b.kind!=='actual'?'<button data-action="deleteBasket" class="btn btn-small btn-danger">Eliminar</button>':''}${detail.my_role!=='owner'?'<button data-action="leaveBasket" class="btn btn-small btn-danger">Salir</button>':''}</div></div>
 <form id="editBasket" class="grid-form" style="margin-top:22px"><label>Nombre<input name="title" value="${esc(b.title)}" ${detail.my_role==='owner'?'':'disabled'}></label><label>Presupuesto máximo (€)<input name="budget_eur" type="number" min="0" step="0.01" value="${b.budget_cents!=null?Number(b.budget_cents/100).toFixed(2):''}" placeholder="Sin límite" ${detail.my_role==='owner'?'':'disabled'}></label>
 <label>Usar en lugar<select name="place_id" ${detail.my_role==='owner'?'':'disabled'}>${placeSelect(b.place_id)}</select></label><label>Fecha del evento<input type="date" name="event_on" value="${esc(b.event_on||'')}" ${detail.my_role==='owner'?'':'disabled'}></label>
 <label class="wide">Notas<textarea name="notes" rows="2" ${detail.my_role==='owner'?'':'disabled'} placeholder="Preferencias, alergias (a confirmar con etiquetas)…">${esc(b.notes||'')}</textarea></label>${detail.my_role==='owner'?'<button class="btn btn-small btn-soft wide">Guardar detalles</button>':''}</form>
 <div class="divider"></div><div class="row"><div><h3>Lista de compra</h3><p>${checked} de ${all} anotaciones marcadas · estado compartido</p></div>${all&&canEdit?`<button data-action="resetChecks" class="btn btn-small btn-secondary">Nueva compra ↺</button>`:pill(all+' artículos')}</div>
 <div class="progress" role="progressbar" aria-valuenow="${checked}" aria-valuemin="0" aria-valuemax="${all||1}"><span style="width:${all?100*checked/all:0}%"></span></div>
 ${all?detail.items.map(i=>{const key=i.item_kind==='free'?`data-free="${i.free_id}"`:`data-pid="${i.product_id}"`;return `<div class="srow ${i.checked?'item-done':''}"><div class="row" style="justify-content:flex-start;gap:12px;flex:1">${canEdit?`<button class="checkbtn ${i.checked?'active':''}" data-action="toggleItem" data-kind="${i.item_kind}" ${key} data-checked="${i.checked?0:1}" aria-label="${i.checked?'Desmarcar':'Marcar'} ${esc(i.name)}">${i.checked?'✓':''}</button>`:`<span class="checkbtn ${i.checked?'active':''}">${i.checked?'✓':''}</span>`}<div><strong>${esc(i.name)}</strong><small>${esc(i.item_kind==='free'?'Anotación privada · sin precio comparable':(i.format_text||i.category))}</small></div></div>
 <div class="qty">${canEdit?`<button data-action="qty" data-kind="${i.item_kind}" ${key} data-qty="${Math.max(0,Number(i.quantity)-1)}" aria-label="Quitar uno">−</button>`:''}<strong>${fmtQty(i.quantity)}</strong>${canEdit?`<button data-action="qty" data-kind="${i.item_kind}" ${key} data-qty="${Number(i.quantity)+1}" aria-label="Añadir uno">+</button>`:''}</div></div>`;}).join(''):shortEmpty('Cesta vacía: escribe lo que necesitas o añade un producto del catálogo.')}
 ${canEdit?`<div class="grid two" style="margin-top:19px;gap:12px"><div class="hint"><strong>Añadir rápido, sin buscar:</strong><form id="quickItem" class="form"><label>Qué necesitas<input name="title" required minlength="1" maxlength="120" placeholder="Pan, 2 yogures, servilletas…"></label><div class="row"><label style="max-width:120px">Cantidad<input name="quantity" type="number" step="0.1" min="0.1" max="1000" value="1" required></label><button class="btn btn-primary">Añadir +</button></div></form></div>
 <div class="hint"><strong>Referencia del catálogo:</strong><form id="basketAddItem" class="form"><label>Producto<select name="product_id" required>${productSelect(null)}</select></label><div class="row"><label style="max-width:120px">Cantidad<input name="quantity" type="number" min="0.1" max="1000" step="0.1" value="1" required></label><button class="btn btn-secondary">Añadir +</button></div></form></div></div>`:''}
 ${pantryOverlap.length?`<div class="hint warn" style="margin-top:16px">💡 Tu despensa ya incluye <strong>${pantryOverlap.map(p=>esc(p.name)).join(', ')}</strong>. Revisa las cantidades antes de comprar.</div>`:''}
 <div class="divider"></div><div class="row"><h3>Comparación de precios</h3><span class="tiny">Presupuesto: ${esc(limit)}</span></div><p>Los textos rápidos se mantienen privados y carecen de precio comparable hasta asociarlos a un producto del catálogo. Nunca calculamos una cesta completa si faltan referencias.</p>
 <button data-action="compare" class="btn btn-primary" style="margin-top:13px">Calcular opciones de compra →</button>${compareData?renderComparison(compareData):''}
 <div class="divider"></div><h3>Compartir y organizar</h3><p>Códigos temporales, con permisos de edición o lectura. Puedes retirar a otra persona o abandonar una cesta compartida.</p>
 ${detail.my_role==='owner'?`<div class="button-row" style="margin-top:12px"><button data-action="basketInvite" data-role="editor" class="btn btn-small btn-soft">Invitar a editar</button><button data-action="basketInvite" data-role="reader" class="btn btn-small btn-secondary">Invitar a consultar</button></div>`:''}
 ${invitation&&invitation.kind==='basket'&&invitation.basketId===basketId?showInvite(invitation):''}
 ${detail.members.length?`<div class="divider"></div><div class="eyebrow">PARTICIPANTES</div>${detail.members.map(m=>`<div class="srow"><strong>👤 ${esc(m.display_name)}</strong><div class="button-row">${pill(m.role)}${detail.my_role==='owner'?`<button data-action="removeMember" data-uid="${m.id}" class="btn btn-small btn-danger">Retirar</button>`:''}</div></div>`).join('')}`:''}
 <div class="button-row" style="margin-top:18px"><button data-nav="orders" class="btn btn-soft">Planificar recogida o entrega →</button><button data-nav="catalog" class="btn btn-secondary">Explorar catálogo</button></div></div>`;
}

function renderComparison(c){if(c.status==='empty')return '<div class="hint warn compare-result">La cesta está vacía.</div>';const full=c.by_store.filter(s=>s.total_cents!=null);const least=full.length?full.slice().sort((a,b)=>a.total_cents-b.total_cents)[0]:null;
 return `<div class="compare-result"><div class="hint ${c.best?'':'warn'}"><strong>Cobertura: ${c.coverage}/${c.total_items} productos</strong> · observaciones comunitarias recientes.<br>${c.best?'Existe combinación con cobertura de la cesta, pero sin garantía de disponibilidad ni precio.':'No hay precios suficientes para calcular una cesta completa.'}</div>
 ${c.unpriced?.length?`<div class="notice alert"><strong>Sin precio reciente en ninguna tienda:</strong> ${c.unpriced.map(esc).join(', ')}</div>`:''}
 ${c.best?`<div class="comparison-card"><div class="row"><div><strong>Mejor combinación modelada</strong><small class="tiny">${esc(c.best.store_names.join(' + '))} · ${c.best.stops} parada(s)</small></div><div class="big-price">${money(c.best.items_total_cents)}</div></div><p>Coste hipotético de parada adicional: ${money(c.best.extra_stop_assumption_cents)} · Objetivo modelado: ${money(c.best.objective_cents)}</p>
 <div class="divider"></div>${c.best.assignment.map(a=>`<div class="srow"><div><strong>${esc(a.product)}</strong><small>${esc(a.store_name)} · ${esc(a.source_type)} · ${friendly(a.observed_at)}</small></div><strong>${money(a.subtotal_cents)}</strong></div>`).join('')}</div>`:''}
 ${full.length?`<div class="subheading" style="margin-top:16px">Cestas completas en una sola tienda</div>${full.sort((a,b)=>a.total_cents-b.total_cents).map(s=>`<div class="srow"><strong>${esc(s.store_name)}</strong><strong>${money(s.total_cents)}</strong></div>`).join('')}`:'<p class="footnote">Ningún supermercado tiene observaciones recientes de todos los artículos.</p>'}
 ${c.product_savings_vs_single_cents!=null?`<div class="hint" style="margin-top:12px">Diferencia en productos frente a la tienda única más barata: ${money(c.product_savings_vs_single_cents)}. No es ahorro neto: faltan desplazamientos y servicio reales.</div>`:''}
 <p class="footnote">${esc(c.assumption||'')}</p></div>`;}
function renderPantry(){const act=activePantry();const closed=state.pantry.filter(x=>x.state!=='active');const inDue=soonPantry();
 return head('COMPRA SOLO LO QUE NECESITAS','Tu despensa','Registra lo que ya tienes. Evita compras duplicadas, revisa fechas y documenta qué has aprovechado o descartado.')+
 `<div class="grid three"><div class="metric"><div class="ic">◷</div><strong>${act.length}</strong><small>Referencias activas</small></div><div class="metric"><div class="ic">☼</div><strong>${inDue.length}</strong><small>Fecha próxima o pasada</small></div><div class="metric"><div class="ic">✓</div><strong>${closed.filter(x=>x.state==='used').length}</strong><small>Registros marcados como utilizados (declarados)</small></div></div>
 <div class="grid two" style="margin-top:17px"><div class="panel"><h3>Añadir a la despensa</h3><form id="pantryAdd" class="form"><label>Producto de tu catálogo (opcional)<select name="product_id">${productSelect(null,'Otro producto / escribir nombre')}</select></label><label>Nombre libre si no está en el catálogo<input name="custom_name" maxlength="100" placeholder="Yogures, tomates, arroz…"></label><div class="grid two"><label>Cantidad<input name="quantity" type="number" step="0.1" min="0.1" value="1" required></label><label>Unidad<select name="unit"><option>ud</option><option>kg</option><option>g</option><option>l</option><option>ml</option></select></label></div><label>Fecha del envase (si aparece)<input name="expires_on" type="date"></label><label>Valor aproximado (€), opcional<input name="value_eur" type="number" min="0" step=".01" placeholder="0,00"></label><button class="btn btn-primary">Guardar producto</button></form><p class="footnote">No confundimos fecha de caducidad con consumo preferente; esta alfa no determina si un alimento es seguro para consumir.</p></div>
 <div class="panel"><div class="row"><h3>Lo que tienes en casa</h3>${pill(act.length+' activos')}</div>${act.length?act.map(i=>`<div class="srow"><div><strong>${esc(i.product_name||i.custom_name)}</strong><small>${fmtQty(i.quantity)} ${esc(i.unit)} · ${i.expires_on?'Fecha anotada: '+esc(i.expires_on):'Sin fecha'} </small></div><div class="portion-controls"><label class="tiny">Cantidad a registrar<input aria-label="Cantidad que has usado o descartado" data-portion="${i.id}" type="number" step="any" min="0.001" max="${i.quantity}" value="${i.quantity}"></label><div class="button-row"><button class="btn btn-small btn-soft" data-action="pantryPortion" data-item="${i.id}" data-status="used">Consumí</button><button class="btn btn-small btn-danger" data-action="pantryPortion" data-item="${i.id}" data-status="discarded">Deseché</button></div></div></div>`).join(''):shortEmpty('Añade tu primer alimento.')}
 <div class="divider"></div><h3>Historial declarado</h3>${state.recent_movements?.length?state.recent_movements.slice(0,12).map(m=>`<div class="srow"><div><strong>${esc(m.product_name||m.custom_name)}</strong><small>${fmtQty(m.quantity)} ${esc(m.unit)} · ${friendly(m.created_at)}</small></div>${pill(m.kind==='used'?'Consumido':'Descartado',m.kind==='used'?'':'red')}</div>`).join(''):closed.length?closed.slice(0,8).map(i=>`<div class="srow"><strong>${esc(i.product_name||i.custom_name)}</strong>${pill(i.state==='used'?'Utilizado (registro anterior)':'Descartado (registro anterior)',i.state==='used'?'':'red')}</div>`).join(''):shortEmpty('Registra las porciones consumidas o descartadas para verlas aquí.')}</div></div>`;}
function filteredProducts(){const q=searchProduct.trim().toLowerCase();return state.products.filter(p=>!q||[p.name,p.category,p.brand_name,p.group_name,p.gtin].some(x=>String(x||'').toLowerCase().includes(q)))}
function productCards(){const products=filteredProducts();return products.length?products.map(p=>{
 const last=state.prices.find(x=>x.product_id===p.id);return `<div class="product-line"><span class="product-icon">${p.category==='Fruta'?'🍎':p.category==='Café'?'☕':'🥫'}</span><div class="body"><h3>${esc(p.name)}</h3><p>${esc(p.category)}${p.brand_name?' · '+esc(p.brand_name):''}${p.format_text?' · '+esc(p.format_text):''}</p><div class="tags">${p.gtin?`<span class="micro">EAN ${esc(p.gtin)}</span>`:''}<span class="micro warn">${esc(p.source_status||'No verificado')}</span></div>${last?`<p>Última observación: ${money(last.amount_cents)} · ${esc(last.store_name)} · ${friendly(last.observed_at)} · sin verificar</p>`:''}</div><button data-action="addProduct" data-pid="${p.id}" class="btn btn-small btn-primary">+ Cesta</button></div>`;}).join(''):shortEmpty('No hay productos que coincidan. Puedes añadir una referencia manual.')}
function renderCatalog(){return head('CARTA INTELIGENTE','Todos los productos','Búsqueda por producto, marca, grupo o código. El catálogo es parcial y las observaciones de precios no demuestran stock en tienda.')+
 `<div class="grid two"><div class="panel"><div class="row top"><div><h3>Explora el catálogo</h3><p>${state.products.length} referencias en el piloto (algunas genéricas).</p></div></div>
 <div class="searchrow"><input class="search" id="productSearch" placeholder="Nutella, café, marca, EAN…" value="${esc(searchProduct)}" aria-label="Buscar productos"></div>
 <label class="tiny">Añadir a la cesta <select id="catalogBasket" class="search">${basketSelect(selectedBasketCatalog)}</select></label>
 <div id="productCards">${productCards()}</div></div>
 <div class="stack"><div class="panel"><h3>Buscar por código de barras</h3><p>Usa el GTIN/EAN o la cámara cuando el navegador lo permita.</p><form class="form" id="barcodeLookup"><label>Código EAN/GTIN<input name="code" required pattern="[0-9]{8,14}" placeholder="3017620422003" maxlength="14"></label><div class="button-row"><button class="btn btn-primary">Consultar</button><button type="button" class="btn btn-secondary" data-action="camera">📷 Escanear</button></div></form><video id="cameraView" class="hidden" playsinline muted style="width:100%;max-height:220px;margin-top:10px;border-radius:12px"></video><div id="barcodeResponse" class="footnote"></div></div>
 <div class="panel"><h3>Crear referencia manual</h3><form id="createProduct" class="form"><label>Nombre completo<input name="name" minlength="2" maxlength="120" required placeholder="Leche entera, marca, 1 L"></label><label>Categoría<input name="category" minlength="2" maxlength="70" required placeholder="Lácteos"></label><label>Formato<input name="format_text" maxlength="35" placeholder="1 L"></label><label>EAN/GTIN (opcional)<input name="gtin" maxlength="14" placeholder="Solo si lo conoces"></label><button class="btn btn-secondary">Crear producto no verificado</button></form></div>
 <div class="panel"><h3>Añadir un precio observado</h3><form id="priceAdd" class="form"><label>Producto<select name="product_id" required>${productSelect(null)}</select></label><label>Supermercado<select name="store_id" required>${storeSelect(null)}</select></label><div class="grid two"><label>Precio (€)<input name="price" type="number" required min=".01" step=".01" placeholder="2,75"></label><label>Fuente<select name="source_type"><option value="etiqueta">Etiqueta en tienda</option><option value="ticket">Ticket</option><option value="anuncio">Anuncio comercial</option></select></label></div><label>Observación <input name="note" maxlength="200" placeholder="Promoción con tarjeta, precio por unidad…"></label><button class="btn btn-primary">Guardar observación</button></form><p class="footnote">Una etiqueta no acredita stock ni un precio idéntico en otras tiendas. No subas datos personales de tickets.</p></div></div></div>`;}
const dist=(a,b,c,d)=>{const R=6371,p=x=>x*Math.PI/180,D=p(c-a),E=p(d-b),aa=Math.sin(D/2)**2+Math.cos(p(a))*Math.cos(p(c))*Math.sin(E/2)**2;return R*2*Math.atan2(Math.sqrt(aa),Math.sqrt(1-aa));};
function listStores(){const q=searchStore.trim().toLowerCase();const network=new Set(state.network.filter(x=>x.place_id===placeId).map(x=>x.store_id));
 let stores=state.stores.filter(s=>!q||[s.name,s.chain,s.address,s.municipality].some(x=>String(x||'').toLowerCase().includes(q)));
 if(geo)stores.sort((a,b)=>(a.lat!=null?dist(geo.lat,geo.lon,a.lat,a.lon):Infinity)-(b.lat!=null?dist(geo.lat,geo.lon,b.lat,b.lon):Infinity));
 return stores.map(s=>`<div class="srow"><div><strong>🏪 ${esc(s.name)}</strong><small>${esc(s.address)}</small><div class="tags">${pill(s.source_type==='aporte_manual_no_verificado'?'Sin verificar: usuario':s.source_type.includes('OpenStreetMap')?'OSM · sin verificar':'Fuente comercial referenciada',s.source_type==='aporte_manual_no_verificado'||s.source_type.includes('OpenStreetMap')?'amber':'')}${network.has(s.id)?pill('En mi red'):''}${geo&&s.lat!=null?pill(dist(geo.lat,geo.lon,s.lat,s.lon).toFixed(1)+' km'):''}</div></div><div class="button-row"><button data-action="openShelf" data-store="${s.id}" class="btn btn-small btn-soft">Carta observada</button>${placeId?`<button data-action="linkStore" data-store="${s.id}" data-save="${network.has(s.id)?'false':'true'}" class="btn btn-small ${network.has(s.id)?'btn-secondary':'btn-primary'}">${network.has(s.id)?'Quitar':'Mi red +'}</button>`:''}</div></div>`).join('')||shortEmpty('No hay tiendas con ese filtro. Añade una tienda manualmente o importa registros con licencia.')}
function renderStores(){const place=state.places.find(p=>p.id===placeId);const network=state.network.filter(x=>x.place_id===placeId);
 return head('TU MAPA COTIDIANO','Lugares y supermercados','Organiza redes como Casa Madrid, Oficina o Casa del pueblo. Las cadenas no tienen todavía una carta conectada de productos ni stock.')+
 `<div class="grid two"><div class="panel"><h3>Mis lugares</h3><div class="stack" style="margin-top:15px">${state.places.map(p=>`<button class="choice ${placeId===p.id?'active':''}" data-select-place="${p.id}"><span class="emoji">📍</span><span><strong>${esc(p.name)}</strong><small>${esc(p.address||'Sin dirección')} · ${state.network.filter(n=>n.place_id===p.id).length} tiendas</small></span></button>`).join('')||shortEmpty('Todavía no tienes lugares guardados.')}</div><div class="divider"></div><h3>Añadir lugar</h3><form id="placeAdd" class="form"><label>Nombre<input name="name" required minlength="2" placeholder="Casa Madrid, Abuelos, Oficina…"></label><label>Dirección opcional<input name="address" maxlength="220" placeholder="No introduzcas una dirección personal real en esta alfa"></label><button class="btn btn-primary">Crear lugar</button></form></div>
 <div class="panel"><div class="row top"><div><h3>${place?'Red de '+esc(place.name):'Directorio de supermercados'}</h3><p>${network.length} establecimientos guardados en este lugar · ${state.stores.length} registros conocidos por el piloto.</p></div><button data-action="locate" class="btn btn-small btn-soft">⌖ Cercanos</button></div>
 <div class="searchrow"><input id="storeSearch" class="search" placeholder="Buscar DIA, calle, localidad…" value="${esc(searchStore)}"></div>
 ${geo?'<div class="hint">Localización del dispositivo activa solo durante esta sesión. Las distancias requieren coordenadas de cada tienda.</div>':''}
 <div id="storesList" style="margin-top:8px;max-height:650px;overflow:auto">${listStores()}</div></div></div>
 <div class="grid two" style="margin-top:16px"><div class="panel"><h3>Establecimiento que falta</h3><form id="storeAdd" class="grid-form"><label>Nombre<input name="name" required minlength="2"></label><label>Cadena<input name="chain" required minlength="2" placeholder="DIA, Lidl, independiente…"></label><label>Dirección<input name="address" required minlength="6"></label><label>Localidad<input name="municipality" placeholder="Alcobendas"></label><button class="btn btn-secondary wide">Añadir sin verificar</button></form><p class="footnote">Las tiendas aportadas se compartirán con otros perfiles de este servidor local. No utilices direcciones de domicilios particulares.</p></div>
 <div class="panel soft"><h3>Un directorio honesto</h3><p>Para completar Madrid se necesitan importaciones con fuente, licencia, limpieza de duplicados y control de establecimientos cerrados. El usuario puede empezar con su red sin esperar a una integración comercial.</p><div class="event-list"><span>Referencia documentada</span><span>Aporte manual</span><span>Ubicación opcional</span><span>Sin inventario oficial</span></div><p class="footnote">Datos cartográficos importados de OpenStreetMap, cuando los haya, bajo © colaboradores de OpenStreetMap / licencia ODbL. No prueba apertura ni exhaustividad.</p></div></div>${renderShelf()}`;}
function renderShelf(){if(!shelfData)return '';const sh=shelfData;
 return `<div id="shelfPanel" class="panel shelf-panel" style="margin-top:18px"><div class="row top"><div><div class="eyebrow">CARTA COMUNITARIA POR TIENDA</div><h2>${esc(sh.store.name)}</h2><p>${esc(sh.store.address)}</p></div>${pill('Parcial · NO oficial','amber')}</div><div class="hint warn">${esc(sh.note)}. Una anotación de «visto» no certifica existencias actuales.</div>
 <div class="grid two" style="margin-top:17px"><div><h3>Productos observados</h3>${sh.items.length?sh.items.map(i=>`<div class="srow"><div><strong>${esc(i.product_name)}</strong><small>${i.last_seen_kind==='seen'?'Visto por una persona':i.last_seen_kind==='not_found'?'No encontrado por una persona':'Sin observación de estantería'}${i.last_seen_at?' · '+friendly(i.last_seen_at):''}</small>${i.price_cents!=null?`<small>${money(i.price_cents)} · precio observado ${friendly(i.price_observed_at)} (sin verificar)</small>`:''}</div><button class="btn btn-small btn-soft" data-action="watchShelfProduct" data-pid="${i.product_id}">Seguir</button></div>`).join(''):shortEmpty('Nadie ha añadido observaciones todavía. Empieza por un producto que hayas comprobado personalmente.')}</div>
 <div><h3>Contribuir a esta carta</h3><form id="shelfObserve" class="form"><input type="hidden" name="store_id" value="${sh.store.id}"><label>Producto<select name="product_id" required>${productSelect(null)}</select></label><label>¿Qué has observado?<select name="kind"><option value="seen">Lo he visto en la tienda</option><option value="not_found">No lo he encontrado</option></select></label><label>Detalle (opcional)<textarea name="note" maxlength="250" placeholder="Pasillo, formato, fecha o información relevante"></textarea></label><button class="btn btn-primary">Guardar observación</button></form><p class="footnote">Cada aporte tiene tienda, producto y fecha. No convierte a SHOPPER en el inventario oficial de la tienda.</p></div></div></div>`;}
function renderWatch(){const w=state.watches||[],alerts=state.watch_alerts||[];
 return head('AHORRA SIN BUSCAR CADA DÍA','Seguimiento de productos','Sigue un producto en todas las tiendas conocidas o en una concreta. Los avisos se basan en aportaciones de la comunidad, no en precios ni stock garantizados.')+
 `<div class="grid three"><div class="metric"><div class="ic">◉</div><strong>${w.length}</strong><small>Seguimientos personales</small></div><div class="metric"><div class="ic">↘</div><strong>${alerts.filter(a=>a.kind==='price').length}</strong><small>Precios bajo objetivo comunicados recientemente</small></div><div class="metric"><div class="ic">↻</div><strong>${alerts.filter(a=>a.kind==='restocked').length}</strong><small>Avisos de reposición comunitarios</small></div></div>
 <div class="grid two" style="margin-top:17px"><div class="panel"><h3>Seguir un producto</h3><form id="watchAdd" class="form"><label>Producto<select name="product_id" required>${productSelect(null)}</select></label><label>Supermercado<select name="store_id"><option value="">Cualquier tienda conocida</option>${opts(state.stores,null,x=>x.name)}</select></label><label>Avísame si su precio observado es igual o inferior a (€)<input name="threshold_eur" type="number" min="0.01" max="10000" step="0.01" placeholder="Opcional, p. ej. 2,99"></label><button class="btn btn-primary">Crear seguimiento</button></form><p class="footnote">El seguimiento sin precio objetivo sirve para avisos recientes de reposición. No enviamos notificaciones push ni consultamos automáticamente inventarios de supermercados.</p></div>
 <div class="panel"><h3>Mis seguimientos</h3>${w.length?w.map(x=>`<div class="srow"><div><strong>${esc(x.product_name)}</strong><small>${esc(x.store_name||'Todas las tiendas conocidas')} · objetivo ${money(x.threshold_cents)}</small></div><button class="btn btn-small btn-danger" data-action="watchDelete" data-id="${x.id}">Eliminar</button></div>`).join(''):shortEmpty('Aún no sigues ningún producto.')}</div></div>
 <div class="panel" style="margin-top:17px"><div class="row"><h3>Novedades para tus seguimientos</h3>${pill('Sin verificar','amber')}</div>${alerts.length?alerts.map(x=>{const watch=w.find(y=>y.id===x.watch_id);return `<div class="srow"><div><strong>${x.kind==='price'?'↘ Precio observado bajo el objetivo':'↻ Alguien comunicó reposición'} · ${esc(watch?.product_name||'Producto')}</strong><small>${esc(x.store_name)} · ${friendly(x.observed_at)}</small></div>${x.amount_cents!=null?`<strong>${money(x.amount_cents)}</strong>`:pill('Comunidad')}</div>`}).join(''):shortEmpty('No hay observaciones posteriores al inicio de tus seguimientos que cumplan tus condiciones.')}</div>`;}
function renderHistory(){const runs=state.shopping_runs||[],spent=runs.reduce((n,x)=>n+x.paid_cents,0),minutes=runs.reduce((n,x)=>n+(x.minutes_spent||0),0);
 return head('MEDIR SIN INVENTAR AHORRO','Mi historial de compras','Registra cuánto has pagado realmente y cuánto tiempo has dedicado. Solo son datos que tú declaras; no los convertimos en ahorro atribuido automáticamente.')+
 `<div class="grid three"><div class="metric"><div class="ic">▤</div><strong>${runs.length}</strong><small>Compras anotadas</small></div><div class="metric"><div class="ic">€</div><strong>${money(spent)}</strong><small>Gasto registrado, no gasto total de tu hogar</small></div><div class="metric"><div class="ic">◷</div><strong>${minutes} min</strong><small>Tiempo registrado</small></div></div>
 <div class="grid two" style="margin-top:17px"><div class="panel"><h3>Registrar una compra realizada</h3><form id="shoppingRunAdd" class="form"><label>Cesta de referencia<select name="basket_id" required>${basketSelect(basketId)}</select></label><label>Supermercado (opcional)<select name="store_id">${storeSelect(null)}</select></label><div class="grid two"><label>Total pagado (€)<input name="paid_eur" type="number" min="0" step=".01" required placeholder="18,70"></label><label>Minutos dedicados<input name="minutes_spent" type="number" min="0" max="1440" placeholder="45"></label></div><label>Notas opcionales<input name="notes" maxlength="350" placeholder="Compra propia, ticket guardado personalmente…"></label><button class="btn btn-primary">Guardar compra declarada</button></form><p class="footnote">La compra no se envía ni se cobra. Se guarda una copia de las líneas de la cesta en ese momento. Si la compra incluye varios supermercados, indica el gasto conjunto y deja la tienda en blanco.</p></div>
 <div class="panel"><h3>Actividad registrada</h3>${runs.length?runs.map(r=>`<div class="srow"><div><strong>${esc(r.basket_name)}</strong><small>${esc(r.store_name||'Multitienda / sin tienda')} · ${friendly(r.recorded_at)} · ${r.minutes_spent==null?'Tiempo no registrado':r.minutes_spent+' min'}</small><small>${esc(r.notes||'Registro personal no verificado')}</small></div><strong>${money(r.paid_cents)}</strong></div>`).join(''):shortEmpty('Anota tu primera compra para empezar a medir gasto y tiempo.')}</div></div>`;}
function renderLive(){return head('EL WAZE DE LOS SUPERMERCADOS','SHOPPER Live','Los vecinos pueden avisar de productos agotados, repuestos, rebajas y novedades en una tienda concreta. Los avisos caducan y admiten corroboraciones.')+
 `<div class="grid two"><div class="panel"><h3>Publicar una novedad</h3><p>Información comunitaria, no certificación oficial ni derecho a exigir un precio.</p><form id="livePost" class="form"><label>Supermercado<select name="store_id" required>${storeSelect(null)}</select></label><label>Producto<select name="product_id" required>${productSelect(null)}</select></label><label>Qué ha ocurrido<select name="kind"><option value="agotado">Se ha agotado</option><option value="repuesto">Lo han repuesto</option><option value="descuento">He visto un descuento</option><option value="nuevo">Producto nuevo</option></select></label><label>Precio rebajado (€), si aplica<input name="price_eur" type="number" min=".01" step=".01" placeholder="Opcional"></label><label>Detalle de la observación<textarea name="note" maxlength="280" placeholder="Dónde lo viste, condiciones de la oferta, estantería…"></textarea></label><button class="btn btn-primary">Publicar aviso</button></form><div class="hint warn" style="margin-top:18px">Por defecto no damos un estado de stock oficial. Una confirmación de usuarios no equivale a inventario conectado.</div></div>
 <div class="panel"><div class="row"><h3>Últimos avisos activos</h3>${pill(state.reports.length+' avisos')}</div>${state.reports.length?state.reports.map(r=>`<div class="report-block"><div class="row top"><div><strong>${{agotado:'🔴 Agotado',repuesto:'🟢 Repuesto',descuento:'🏷️ Descuento',nuevo:'✨ Novedad'}[r.kind]||esc(r.kind)} · ${esc(r.product_name)}</strong><div class="tiny">${esc(r.store_name)} · ${friendly(r.created_at)}</div></div>${pill(r.confirmations+' conf.','slate')}</div><p>${esc(r.note||'Sin detalles adicionales.')}</p>${r.price_cents?`<div class="stat" style="margin-top:7px">Precio comunicado: ${money(r.price_cents)}</div>`:''}<div class="buttons">${r.reporter_id===state.me.id?pill('Tu aviso'):r.i_confirmed?pill('Confirmado por ti'):`<button data-action="confirmReport" data-id="${r.id}" class="btn btn-small btn-soft">Corroborar</button>`}<button data-action="flagReport" data-id="${r.id}" class="btn btn-small btn-secondary">Reportar error</button></div><div class="footnote">${esc(r.reporter_name)} · caduca ${friendly(r.expires_at)}</div></div>`).join(''):shortEmpty('Publica el primer aviso observado.')}</div></div>`;}
function renderCommunity(){return head('CONOCE LO QUE COMPRAS','Foodpedia & comunidad','Relaciones entre marcas, grupos y productos, información del envase y valoraciones. Separamos hechos verificables de opiniones.')+
 `<div class="grid two"><div class="panel"><div class="row"><h3>El mapa de las marcas</h3>${pill(state.brands.length+' relaciones')}</div>${state.brands.map(b=>`<div class="srow"><div><strong>${esc(b.name)} <span style="color:#a2b5a2">→</span> ${esc(b.group_name)}</strong><small>Relación corporativa documentada; no identifica dónde se fabricó un lote.</small><a class="tiny" target="_blank" rel="noopener noreferrer" href="${esc(b.evidence_url||b.group_source||'#')}">Ver fuente corporativa ↗</a></div></div>`).join('')}
 <div class="divider"></div><h3>Ficha nutricional: límites</h3><p>Ingredientes, alérgenos y origen deben proceder de etiquetas o fuentes documentadas. El EAN no demuestra el país de fabricación. La valoración subjetiva no constituye un Nutri-Score.</p></div>
 <div class="stack"><div class="panel"><h3>Valorar un producto</h3><form id="reviewPost" class="form"><label>Producto<select name="product_id" required>${productSelect(null)}</select></label><div class="grid two"><label>Calidad percibida<select name="quality">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} / 5</option>`).join('')}</select></label><label>Calidad / precio<select name="value">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} / 5</option>`).join('')}</select></label></div><label>Tu opinión<textarea name="comment" minlength="3" maxlength="600" required placeholder="Qué te gusta o qué mejorarías"></textarea></label><button class="btn btn-primary">Publicar valoración</button></form></div>
 <div class="panel"><h3>Opiniones de la comunidad</h3>${state.reviews.length?state.reviews.map(r=>`<div class="srow"><div><strong>${esc(r.product_name)}</strong><small>Calidad ${r.quality}/5 · Precio ${r.value}/5 · ${esc(r.reviewer_name)}</small><p>${esc(r.comment)}</p></div></div>`).join(''):shortEmpty('Todavía no hay valoraciones.')}</div></div></div>`;}
function renderOrders(){const chosen=state.baskets.find(x=>x.id===basketId);return head('COMPRA PLANIFICADA','Recogidas y entregas','Organiza un borrador de compra con antelación y ventana de 15–120 minutos. No hay pagos, asignación ni preparación por el establecimiento.')+
 `<div class="grid two"><div class="panel"><div class="row"><h3>Nuevo borrador</h3>${pill('No se envía','amber')}</div><form id="orderDraft" class="form"><label>Cesta<select name="basket_id" required>${basketSelect(basketId)}</select></label><label>Modalidad<select name="mode"><option value="self_shop">Ir a comprar yo mismo</option><option value="pickup_shopper">SHOPPER Pickup · un shopper compra, recoge cliente</option><option value="delivery_shopper">SHOPPER Delivery · un shopper compra y entrega</option><option value="pickup_store">Preparada por el supermercado (todavía NO disponible)</option></select></label>
 <label>Supermercado para compra / último encuentro<select name="store_id">${storeSelect(null)}</select></label><label>Destino personal (para Delivery)<select name="place_id">${placeSelect(chosen?.place_id)}</select></label>
 <label>Persona que recibirá (alias, opcional)<input name="recipient_alias" maxlength="80" placeholder="Papá, Tía, yo…"></label><label>Fecha y hora de comienzo<input name="window_start" type="datetime-local" value="${tomorrow()}" required></label><div class="grid two"><label>Amplitud de ventana<select name="window_mins"><option value="15">15 min (precisa)</option><option value="30">30 min</option><option value="60" selected>1 hora</option><option value="120">2 horas (flexible)</option></select></label><label>Antelación mínima<select name="notice_hours"><option value="0">Urgente / inmediata</option><option value="1">1 hora</option><option value="6" selected>6 horas</option><option value="24">24 horas</option><option value="48">48 horas</option></select></label></div><button class="btn btn-primary">Guardar borrador de planificación</button></form><p class="footnote">Pickup con shopper: entrega completa junto a la última tienda en un punto viable, no un pedido preparado por empleados. La franja no está reservada.</p></div>
 <div class="panel"><div class="row"><h3>Mis borradores</h3>${pill(state.drafts.length+' simulaciones')}</div>${state.drafts.length?state.drafts.map(d=>`<div class="srow"><div><strong>◫ #${d.id} · ${esc(d.mode.replaceAll('_',' '))}</strong><small>${friendly(d.window_start)} · ${d.window_mins} min · previo ${d.notice_hours} h</small>${d.recipient_alias?`<small>Para ${esc(d.recipient_alias)}</small>`:''}</div>${pill('NO ENVIADO','amber')}</div>`).join(''):shortEmpty('Todavía no tienes borradores de encargo.')}
 <div class="divider"></div><div class="hint warn"><strong>Qué falta para realizar operaciones:</strong> acuerdos, seguridad alimentaria, pagos regulados, condiciones de consumo y encuadramiento laboral de shoppers. Un borrador no contacta con supermercados ni profesionales.</div></div></div>`;}
function renderCircle(){
 const tasks=state.family_tasks||[], open=tasks.filter(t=>['open','accepted'].includes(t.status));
 const myBaskets=state.baskets.filter(b=>b.my_role!=='reader');
 const statusLabels={open:'Por hacer',accepted:'En marcha',done:'Terminado',cancelled:'Cancelado'};
 const taskCards=tasks.length?tasks.map(t=>{
  const isMine=t.created_by===state.me.id, canAccept=t.status==='open'&&(!t.assigned_to||t.assigned_to===state.me.id),
        canDone=t.status==='accepted'&&t.assigned_to===state.me.id;
  return `<div class="task-card"><div class="row top"><div><span class="task-state st-${esc(t.status)}">${esc(statusLabels[t.status]||t.status)}</span>
   <h3>${esc(t.title)}</h3><p>${esc(t.basket_name)} · por ${esc(t.creator_name)}</p></div><span class="feature-glyph">${t.status==='done'?'✓':'🛍️'}</span></div>
   ${t.note?`<p class="task-note">${esc(t.note)}</p>`:''}
   <div class="task-meta">${t.assignee_name?'👤 '+esc(t.assignee_name):'👥 Para miembros de la cesta'}${t.due_on?' · 📅 '+esc(t.due_on):''}${t.store_name?' · 📍 '+esc(t.store_name):''}</div>
   <div class="button-row">${canAccept?`<button class="btn btn-small btn-primary" data-action="taskState" data-id="${t.id}" data-status="accepted">Me encargo</button>`:''}
   ${canDone?`<button class="btn btn-small btn-primary" data-action="taskState" data-id="${t.id}" data-status="done">Lo he hecho ✓</button>`:''}
   ${isMine&&t.status!=='done'&&t.status!=='cancelled'?`<button class="btn btn-small btn-secondary" data-action="taskState" data-id="${t.id}" data-status="cancelled">Cancelar</button>`:''}
   <button class="btn btn-small btn-soft" data-open-basket="${t.basket_id}">Abrir cesta ↗</button></div></div>`}).join(''):
   `<div class="empty-circle"><div>🤝</div><h3>Tu círculo empieza con una cesta</h3><p>Crea una cesta compartida, invita a alguien y dejad un recado sencillo para coordinar vuestra compra.</p></div>`;
 return head('SHOPPER CÍRCULO','Un recado. Una cesta. Todos coordinados.','Para tu pareja, tus padres o familiares: crea tareas compartidas y evita mensajes perdidos. Solo entre personas invitadas; sin compras ni pagos a supermercados.')+
 `<div class="circle-banner"><div><span class="eyebrow">TU RED DE CONFIANZA</span><h2>La compra se hace más ligera cuando se comparte.</h2><p>Las tareas solo son visibles para quienes tengan acceso a la cesta. Puedes revocar esos permisos.</p></div><span class="circle-art">🤝</span></div>
 <div class="grid two" style="margin-top:18px"><div class="panel"><div class="row"><h3>Encargar un recado</h3>${pill('Sin reserva comercial')}</div><p>Es una coordinación personal entre familiares; ningún comercio recibe este recado.</p>
 <form class="form" id="familyTaskCreate"><label>¿Qué hay que hacer?<input name="title" required minlength="3" maxlength="110" placeholder="Comprar la cesta de la abuela"></label>
 <label>Cesta compartida<select name="basket_id" required><option value="">Elige una cesta</option>${opts(myBaskets,null,b=>b.title)}</select></label>
 <label>Persona (opcional)<select name="assigned_to"><option value="">Cualquiera con acceso a la cesta</option>${opts(state.friends,null,f=>f.display_name)}</select></label>
 <label>Supermercado de referencia (opcional)<select name="store_id">${storeSelect(null)}</select></label>
 <label>Para qué día (opcional)<input name="due_on" type="date"></label>
 <label>Detalles para la persona que lo hará<textarea name="note" maxlength="300" placeholder="Revisa qué queda y confirma antes de comprar…"></textarea></label>
 <button class="btn btn-primary">Crear recado compartido ↗</button></form>
 <div class="hint warn" style="margin-top:12px">Si eliges una persona, primero debes darle acceso a la cesta mediante una invitación. No se comparten automáticamente domicilios privados.</div></div>
 <div class="panel"><div class="row"><h3>Actividad del círculo</h3>${pill(open.length+' en curso')}</div><div class="task-stack">${taskCards}</div></div></div>`;
}
function renderShopper(){const s=state.shopper||{status:'not_applied'};return head('UNA CUENTA, DOS CAPACIDADES','Trabajar como shopper','Configura cómo te interesaría trabajar. La solicitud no activa automáticamente trabajo real y debe pasar un proceso jurídico y operativo.')+
 `<div class="grid two"><div class="panel"><div class="row"><h3>Mi acceso profesional</h3>${pill(s.status==='not_applied'?'No solicitado':s.status==='draft'?'Borrador de preferencias':s.status==='pending_mock_review'?'En revisión simulada':s.status,'amber')}</div><p>Como consumidor puedes seguir creando cestas mientras solicitas habilitación. Los permisos profesionales serán independientes de tu identidad.</p><form id="shopperPrefs" class="form"><label>Medio de movilidad<select name="travel_mode"><option value="walking" ${s.travel_mode==='walking'?'selected':''}>A pie</option><option value="bike" ${s.travel_mode==='bike'?'selected':''}>Bicicleta</option><option value="car" ${s.travel_mode==='car'?'selected':''}>Coche</option><option value="transit" ${s.travel_mode==='transit'?'selected':''}>Transporte público</option></select></label>
 <label>Antelación mínima para aceptar pedidos<select name="min_notice_hours">${[0,1,6,12,24,48].map(n=>`<option value="${n}" ${n===Number(s.min_notice_hours??6)?'selected':''}>${n===0?'Urgentes / sin antelación':n+' horas'}</option>`).join('')}</select></label>
 <label>Ventana mínima de recogida/entrega<select name="min_window_mins">${[15,30,60,120].map(n=>`<option value="${n}" ${n===Number(s.min_window_mins??60)?'selected':''}>${n} minutos</option>`).join('')}</select></label>
 <label>Radio máximo de movilidad (km)<input name="max_distance_km" type="number" min="1" max="80" value="${Number(s.max_distance_km??5)}" required></label><label>Disponibilidad habitual<textarea name="availability_note" maxlength="400" placeholder="Lunes a viernes después de las 18, zona norte…">${esc(s.availability_note||'')}</textarea></label><button class="btn btn-secondary">Guardar mis preferencias</button></form>
 ${s.status==='not_applied'||s.status==='draft'?'<button class="btn btn-primary" data-action="shopperApply" style="margin-top:13px">Iniciar solicitud de prueba →</button>':''}</div>
 <div class="panel soft"><h3>Interest Packs y Homebound Mode</h3><p>En un producto operativo se podrán seleccionar zonas, comercios, medios de transporte, remuneración mínima y encargos compatibles con el camino de vuelta a casa.</p><div class="divider"></div><h3>Qué necesita una activación real</h3><div class="event-list"><span>Identificación verificada</span><span>Relación contractual</span><span>Seguro y formación</span><span>Medios de transporte</span><span>Pagos habilitados</span></div><div class="hint warn" style="margin-top:20px">La configuración de este piloto no es una relación de trabajo ni permite aceptar encargos remunerados. El modelo laboral depende del funcionamiento real de la plataforma.</div></div></div>`;}
function renderBusiness(){return head('NEGOCIO CON SENTIDO','Economía por encargo','El objetivo es generar utilidad sin destruir margen: remuneración justa, rutas cortas, menos desperdicio y contribución positiva por pedido.')+
 `<div class="grid two"><div class="panel"><h3>Simular una operación</h3><p>Hipótesis libres sin IVA. Ajusta el servicio y costes esperados. Ninguno procede de una cotización operativa.</p><form id="economicCalc" class="grid-form"><label>Tarifa sin IVA (€)<input name="customer_fee_eur" type="number" value="16" step=".01" min="0" required></label><label>Remuneración y cargas (€)<input name="worker_eur" type="number" value="10" step=".01" min="0" required></label><label>Desplazamientos (€)<input name="transport_eur" type="number" value="1.40" step=".01" min="0" required></label><label>Procesamiento pagos (€)<input name="payment_eur" type="number" value="0.60" step=".01" min="0" required></label><label>Soporte (€)<input name="support_eur" type="number" value="0.40" step=".01" min="0" required></label><label>Reserva incidencias (€)<input name="reserve_eur" type="number" value="0.80" step=".01" min="0" required></label><label class="wide">Costes fijos mensuales (€)<input name="monthly_fixed_eur" type="number" value="1500" step="10" min="0" required></label><button class="btn btn-primary wide">Calcular contribución y umbral</button></form></div>
 <div class="panel soft"><div class="eyebrow">ESCENARIO ECONÓMICO</div><h2 style="margin-top:6px">${econ?numMoney(econ.contribution_per_order_eur):'Aún sin calcular'}</h2><p>Contribución estimada por pedido, ANTES de costes fijos.</p><div class="divider"></div><h3>${econ?(econ.orders_to_cover_fixed==null?'No cubre costes fijos':econ.orders_to_cover_fixed+' pedidos/mes'):'¿Cuántos pedidos hacen falta?'}</h3><p>${econ?esc(econ.note):'Introduce datos para calcular una referencia aproximada.'}</p><div class="divider"></div><h3>Qué mediremos de verdad</h3><div class="event-list"><span>Repetición de uso</span><span>Cobertura de precios</span><span>Minutos ahorrados</span><span>Coste por encargo</span><span>Reparto evitado</span><span>Producto consumido o descartado</span></div><p class="footnote">No atribuir causalmente reducción de CO₂, desperdicio o ahorro financiero sin metodología y referencia.</p></div></div>`;}
function renderAccount(){return head('TU IDENTIDAD','Mi cuenta y proyecto','Una única identidad, sesiones privadas y permisos independientes para cestas y funciones profesionales.')+
 `<div class="grid two"><div class="panel"><div class="row"><h3>Mi perfil</h3>${pill('Beta privada','amber')}</div><div class="srow"><strong>Usuario</strong><span>${esc(state.me.username)}</span></div><div class="srow"><strong>Nombre visible</strong><span>${esc(state.me.display_name)}</span></div><div class="srow"><strong>Cestas accesibles</strong><span>${state.baskets.length}</span></div><div class="srow"><strong>Amigos aceptados</strong><span>${state.friends.length}</span></div><div class="srow"><strong>Solicitudes shopper</strong><span>${esc(state.shopper.status)}</span></div><div class="button-row" style="margin-top:20px"><button data-action="download" class="btn btn-secondary">Exportar mis datos (JSON)</button><button data-action="logout" class="btn btn-danger">Cerrar sesión</button></div><div class="divider"></div><h3>Protege tu cuenta</h3>
 <form class="form" id="changePassword"><label>Contraseña actual<input name="current_password" type="password" autocomplete="current-password" required></label>
 <label>Nueva contraseña (12 caracteres o más)<input name="new_password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label>
 <button class="btn btn-secondary">Cambiar contraseña y cerrar otras sesiones</button></form>
 <div class="divider"></div><h3>Pruebas y comentarios</h3><form id="sendFeedback" class="form"><label>Área<select name="area"><option value="usabilidad">Usabilidad</option><option value="cestas">Cestas</option><option value="precios">Precios</option><option value="desperdicio">Desperdicio</option><option value="negocio">Modelo de negocio</option></select></label><label>Qué mejorar<textarea name="note" minlength="3" maxlength="1000" required></textarea></label><button class="btn btn-secondary">Guardar comentario en servidor local</button></form></div>
 <div class="panel soft"><div class="eyebrow">PRESENTE Y PRÓXIMOS PASOS</div><h3>Qué puedes probar en SHOPPER 9.0</h3><div class="event-list"><span>✓ Usuario y contraseña</span><span>✓ Sesiones</span><span>✓ Cestas multiusuario</span><span>✓ Invitaciones</span><span>✓ Despensa</span><span>✓ Observaciones</span><span>✓ API REST</span><span>✓ SQLite</span></div><div class="divider"></div><h3>Qué no se debe prometer</h3><div class="event-list"><span>✕ Reservas en supermercados</span><span>✕ Precios oficiales</span><span>✕ Inventario en directo</span><span>✕ Pagos reales</span><span>✕ Trabajo habilitado</span><span>✕ App Store</span><span>✕ Auditoría de seguridad pública</span></div><p class="footnote">Beta limitada para personas de confianza con servidor privado por HTTPS. Antes de lanzar públicamente necesitaremos verificación de email, auditoría, moderación, backups y RGPD.</p></div></div>
 <div class="section-title"><h2>Explorar las demás funciones</h2></div><div class="grid three">${Object.keys(SECTION).filter(x=>x!=='account').map(k=>`<button data-nav="${k}" class="entry-card"><span class="emoji">→</span><span><strong>${esc(SECTION[k])}</strong></span></button>`).join('')}</div>`;}
async function openBasket(bid){basketId=Number(bid);compareData=null;basketDetail=await api('/api/baskets/'+basketId);render()}
async function doSubmit(e){const form=e.target;if(!form.id)return;const n=form.id;const d=formdata(form);if(!['loginForm','registerForm','createBasket','redeemInvitation','editBasket','basketAddItem','quickItem','pantryAdd','createProduct','priceAdd','placeAdd','storeAdd','barcodeLookup','livePost','reviewPost','orderDraft','shopperPrefs','economicCalc','sendFeedback','shelfObserve','watchAdd','shoppingRunAdd','familyTaskCreate','changePassword'].includes(n))return;e.preventDefault();
 try{if(n==='loginForm'){await authLogin(d.username,d.password);return}
 if(n==='registerForm'){const r=await api('/api/auth/register','POST',{username:d.username,display_name:d.display_name,password:d.password,signup_code:d.signup_code||null});csrf=r.csrf;sessionReady=true;await refresh(false);toast('Cuenta creada, bienvenida');applyIncomingInvite();return}
 if(n==='createBasket'){const r=await api('/api/baskets','POST',{title:d.title,kind:d.kind});basketId=r.id;compareData=null;await refresh();return}
 if(n==='redeemInvitation'){await api('/api/invitations/redeem','POST',{code:d.code});invitation=null;prefillInvite='';if(location.protocol==='http:'||location.protocol==='https:')window.history.replaceState({},'',location.pathname);await refresh();toast('Invitación aceptada, cesta compartida lista');return}
 if(n==='editBasket'){compareData=null;await api('/api/baskets/'+basketId,'PATCH',{title:d.title,place_id:d.place_id?Number(d.place_id):null,budget_cents:d.budget_eur?Math.round(Number(d.budget_eur)*100):null,event_on:d.event_on||null,notes:d.notes});await refresh();toast('Cesta guardada');return}
 if(n==='quickItem'){await api(`/api/baskets/${basketId}/free-items`,'POST',{title:d.title,quantity:Number(d.quantity)});compareData=null;await refresh();toast('Añadido a la cesta');return}
 if(n==='basketAddItem'){compareData=null;const detail=basketDetail;const id=Number(d.product_id);const existing=detail.items.find(x=>x.product_id===id);await api(`/api/baskets/${basketId}/items/${id}`,'PUT',{quantity:Number(d.quantity)+(existing?.quantity||0)});await refresh();toast('Añadido a la cesta');return}
 if(n==='pantryAdd'){await api('/api/pantry','POST',{product_id:d.product_id?Number(d.product_id):null,custom_name:d.custom_name||null,quantity:Number(d.quantity),unit:d.unit,expires_on:d.expires_on||null,estimated_value_cents:d.value_eur?Math.round(Number(d.value_eur)*100):null});await refresh();toast('Despensa actualizada');return}
 if(n==='createProduct'){await api('/api/products','POST',{name:d.name,category:d.category,format_text:d.format_text,gtin:d.gtin||null});await refresh();toast('Producto creado sin verificar');return}
 if(n==='priceAdd'){await api('/api/prices','POST',{product_id:Number(d.product_id),store_id:Number(d.store_id),amount_cents:Math.round(Number(d.price)*100),source_type:d.source_type,note:d.note});await refresh();toast('Precio observado guardado · sin verificar');return}
 if(n==='placeAdd'){const res=await api('/api/places','POST',{name:d.name,address:d.address||null});placeId=res.id;await refresh();toast('Lugar guardado');return}
 if(n==='storeAdd'){await api('/api/stores','POST',{name:d.name,chain:d.chain,address:d.address,municipality:d.municipality});await refresh();toast('Tienda añadida como no verificada');return}
 if(n==='barcodeLookup'){const res=await api('/api/barcodes/'+encodeURIComponent(d.code));$('barcodeResponse').innerHTML=`<p>${res.found?'Producto local: '+esc(res.product.name):'Código válido pero sin ficha local.'} · Ninguna fuente acredita stock o precio en tienda.</p><button class="btn btn-small btn-secondary" data-action="offLookup" data-code="${esc(d.code)}">Consultar Open Food Facts (opcional)</button>`;return}
 if(n==='livePost'){await api('/api/live','POST',{store_id:Number(d.store_id),product_id:Number(d.product_id),kind:d.kind,note:d.note||'',price_cents:d.price_eur?Math.round(Number(d.price_eur)*100):null});await refresh();toast('Aviso publicado sin verificar');return}
 if(n==='reviewPost'){await api('/api/reviews','POST',{product_id:Number(d.product_id),quality:Number(d.quality),value:Number(d.value),comment:d.comment});await refresh();toast('Valoración registrada');return}
 if(n==='orderDraft'){await api('/api/order-drafts','POST',{basket_id:Number(d.basket_id),store_id:d.store_id?Number(d.store_id):null,place_id:d.place_id?Number(d.place_id):null,mode:d.mode,window_start:d.window_start,window_mins:Number(d.window_mins),notice_hours:Number(d.notice_hours),recipient_alias:d.recipient_alias||''});await refresh();toast('Borrador guardado — NO se envió');return}
 if(n==='shopperPrefs'){await api('/api/shopper/profile','POST',{travel_mode:d.travel_mode,min_notice_hours:Number(d.min_notice_hours),min_window_mins:Number(d.min_window_mins),max_distance_km:Number(d.max_distance_km),availability_note:d.availability_note||''});await refresh();toast('Preferencias profesionales guardadas');return}
 if(n==='shelfObserve'){await api('/api/store-sightings','POST',{store_id:Number(d.store_id),product_id:Number(d.product_id),kind:d.kind,note:d.note||''});shelfData=await api('/api/stores/'+d.store_id+'/shelf');await refresh();toast('Observación de estantería guardada · comunitaria');return}
 if(n==='watchAdd'){await api('/api/watches','POST',{product_id:Number(d.product_id),store_id:d.store_id?Number(d.store_id):null,threshold_cents:d.threshold_eur?Math.round(Number(d.threshold_eur)*100):null});await refresh();toast('Seguimiento guardado, sin alertas push');return}
 if(n==='shoppingRunAdd'){await api('/api/shopping-runs','POST',{basket_id:Number(d.basket_id),store_id:d.store_id?Number(d.store_id):null,paid_cents:Math.round(Number(d.paid_eur)*100),minutes_spent:d.minutes_spent?Number(d.minutes_spent):null,notes:d.notes||''});await refresh();toast('Compra real declarada guardada · no enviada');return}
 if(n==='economicCalc'){const body=Object.fromEntries(Object.entries(d).map(([k,v])=>[k,Number(v)]));econ=await api('/api/economics','POST',body);render();return}
 if(n==='familyTaskCreate'){await api('/api/family/tasks','POST',{
  basket_id:Number(d.basket_id),title:d.title,note:d.note||'',due_on:d.due_on||null,
  store_id:d.store_id?Number(d.store_id):null,assigned_to:d.assigned_to?Number(d.assigned_to):null});
  await refresh();toast('Recado creado dentro de tu círculo');return}
 if(n==='changePassword'){const r=await api('/api/auth/change-password','POST',{current_password:d.current_password,new_password:d.new_password});
   csrf=r.csrf;form.reset();toast('Contraseña cambiada; otras sesiones cerradas');return}
 if(n==='sendFeedback'){await api('/api/feedback','POST',{area:d.area,note:d.note});form.reset();toast('Feedback guardado localmente');return}
 }catch(err){toast(err.message,true)}}
async function clickAction(e){const node=e.target.closest('button');if(!node)return;
 try{if(node.dataset.demo){await authLogin(node.dataset.demo,'ShopperDemo2026!');return}
 if(node.id==='showLogin'||node.id==='showRegister'){const register=node.id==='showRegister';$('registerForm').classList.toggle('hidden',!register);$('loginForm').classList.toggle('hidden',register);$('showLogin').classList.toggle('active',!register);$('showRegister').classList.toggle('active',register);return}
 if(node.dataset.nav){goto(node.dataset.nav);return}
 if(node.dataset.openBasket){await openBasket(node.dataset.openBasket);return}
 if(node.dataset.selectPlace){placeId=Number(node.dataset.selectPlace);render();return}
 const a=node.dataset.action;if(!a)return;
 if(a==='qty'){if(node.dataset.kind==='free'){await api(`/api/baskets/${basketId}/free-items/${node.dataset.free}`,'PATCH',{quantity:Number(node.dataset.qty)})}else{await api(`/api/baskets/${basketId}/items/${node.dataset.pid}`,'PUT',{quantity:Number(node.dataset.qty)})}compareData=null;await refresh();return}
 if(a==='toggleItem'){if(node.dataset.kind==='free'){await api(`/api/baskets/${basketId}/free-items/${node.dataset.free}`,'PATCH',{checked:node.dataset.checked==='1'})}else{await api(`/api/baskets/${basketId}/items/${node.dataset.pid}/check`,'PATCH',{checked:node.dataset.checked==='1'})}await refresh();return}
 if(a==='resetChecks'){await api(`/api/baskets/${basketId}/reset-checks`,'POST');await refresh();toast('Marcas reiniciadas para nueva compra');return}
 if(a==='refreshBasket'){basketDetail=await api(`/api/baskets/${basketId}`);await refresh();toast('Cesta sincronizada con el servidor');return}
 if(a==='leaveBasket'){await api(`/api/baskets/${basketId}/members/${state.me.id}`,'DELETE');basketId=null;await refresh(false);toast('Has dejado de compartir esa cesta');return}
 if(a==='removeMember'){await api(`/api/baskets/${basketId}/members/${node.dataset.uid}`,'DELETE');await refresh();toast('Acceso retirado');return}
 if(a==='removeFriend'){await api(`/api/friends/${node.dataset.uid}`,'DELETE');await refresh();toast('Amistad desconectada');return}
 if(a==='copyActual'){if(!confirm('¿Sumar los productos de esta cesta a tu Actual?'))return;const r=await api(`/api/baskets/${basketId}/copy-to-actual`,'POST');basketId=r.target_id;await openBasket(basketId);await refresh();toast(r.copied_lines+' líneas copiadas a la cesta Actual');return}
 if(a==='pantryPortion'){const pid=Number(node.dataset.item);const inp=document.querySelector(`[data-portion="${pid}"]`);const qty=Number(inp?.value);if(!(qty>0))throw Error('La cantidad debe ser positiva');await api('/api/pantry/'+pid+'/portion','POST',{quantity:qty,kind:node.dataset.status});await refresh();toast('Cantidad registrada y despensa actualizada');return}
 if(a==='openShelf'){selectedStoreId=Number(node.dataset.store);shelfData=await api(`/api/stores/${selectedStoreId}/shelf`);render();setTimeout(()=>$('shelfPanel')?.scrollIntoView({behavior:'smooth',block:'start'}),20);return}
 if(a==='watchShelfProduct'){await api('/api/watches','POST',{product_id:Number(node.dataset.pid),store_id:selectedStoreId});await refresh();toast('Producto añadido a tus seguimientos');return}
 if(a==='watchDelete'){await api('/api/watches/'+node.dataset.id,'DELETE');await refresh();toast('Seguimiento eliminado');return}
 if(a==='duplicateBasket'){const r=await api(`/api/baskets/${basketId}/duplicate`,'POST');basketId=r.id;compareData=null;await refresh();toast('Cesta duplicada');return}
 if(a==='deleteBasket'){if(!confirm('¿Eliminar esta cesta y su contenido?'))return;await api(`/api/baskets/${basketId}`,'DELETE');basketId=null;compareData=null;await refresh(false);toast('Cesta eliminada');return}
 if(a==='basketInvite'){const r=await api(`/api/baskets/${basketId}/invite`,'POST',{role:node.dataset.role});invitation={...r,kind:'basket',basketId};render();return}
 if(a==='friendInvite'){const r=await api('/api/friends/invite','POST');invitation={...r,kind:'friend'};render();return}
 if(a==='shareInvite'){const url=location.origin+'/?invite='+encodeURIComponent(node.dataset.code);
  if(navigator.share){try{await navigator.share({title:'Una cesta contigo en SHOPPER',text:'Te invito a compartir una cesta o unirte a mi círculo privado.',url})}catch{}}
  else try{await navigator.clipboard.writeText(url);toast('Enlace privado copiado, envíalo por WhatsApp')}catch{window.prompt('Copia el enlace',url)}return}
 if(a==='copy'){try{await navigator.clipboard.writeText(node.dataset.code);toast('Código copiado')}catch{window.prompt('Copia este código',node.dataset.code)}return}
 if(a==='taskState'){await api('/api/family/tasks/'+node.dataset.id,'PATCH',{status:node.dataset.status});await refresh();toast('Recado actualizado para el círculo');return}
 if(a==='compare'){compareData=await api(`/api/baskets/${basketId}/compare?days=14&extra_stop_cents=300`);render();return}
 if(a==='pantryClose'){await api('/api/pantry/'+node.dataset.item,'PATCH',{state:node.dataset.status});await refresh();toast('Registro de despensa actualizado');return}
 if(a==='addProduct'){const bid=Number($('catalogBasket').value||selectedBasketCatalog);const id=Number(node.dataset.pid);const b=await api('/api/baskets/'+bid);const old=b.items.find(i=>i.product_id===id);await api(`/api/baskets/${bid}/items/${id}`,'PUT',{quantity:Number(old?.quantity||0)+1});selectedBasketCatalog=bid;await refresh();toast('Añadido a '+b.basket.title);return}
 if(a==='linkStore'){if(!placeId)throw Error('Primero añade o selecciona un lugar');await api(`/api/places/${placeId}/stores`,'POST',{store_id:Number(node.dataset.store),save:node.dataset.save==='true'});await refresh();toast('Red de supermercados actualizada');return}
 if(a==='locate'){if(!navigator.geolocation)throw Error('Tu navegador no dispone de geolocalización');navigator.geolocation.getCurrentPosition(pos=>{geo={lat:pos.coords.latitude,lon:pos.coords.longitude};render();toast('Ubicación usada solo para ordenar esta pantalla')},err=>toast('Permiso denegado o posición no disponible: '+err.message,true),{enableHighAccuracy:false,timeout:9000,maximumAge:60000});return}
 if(a==='confirmReport'){await api(`/api/live/${node.dataset.id}/confirm`,'POST');await refresh();toast('Aviso corroborado, sin equivaler a inventario oficial');return}
 if(a==='flagReport'){const reason=prompt('¿Por qué este aviso parece incorrecto?');if(!reason)return;await api(`/api/live/${node.dataset.id}/flag`,'POST',{reason});await refresh();toast('Aviso señalado para revisión');return}
 if(a==='shopperApply'){await api('/api/shopper/apply','POST');await refresh();toast('Solicitud SIMULADA iniciada, sin habilitación de trabajo');return}
 if(a==='logout'){await api('/api/auth/logout','POST');csrf='';sessionReady=false;showAuth();toast('Has cerrado sesión');return}
 if(a==='download'){const data=await api('/api/account/export');const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(b);const link=document.createElement('a');link.href=url;link.download='shopper-mi-cuenta.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);return}
 if(a==='offLookup'){const r=await api('/api/barcodes/'+encodeURIComponent(node.dataset.code)+'/external');const t=$('barcodeResponse');if(!t)return;t.innerHTML=r.found?`<div class="hint"><strong>${esc(r.name||'Sin nombre')}</strong><p>${esc(r.brands||'Marca no indicada')} · ${esc(r.quantity||'Formato no indicado')}</p><p>${esc(r.ingredients||'Ingredientes no disponibles')}</p><p>${esc(r.note)}</p><a target="_blank" rel="noopener noreferrer" href="${esc(r.url)}">Ver ficha de Open Food Facts ↗</a></div>`:`<div class="hint warn">Sin ficha externa disponible. <a target="_blank" rel="noopener noreferrer" href="${esc(r.url)}">Comprobar web de Open Food Facts</a></div>`;return}
 if(a==='camera'){await startCamera();return}
 }catch(err){toast(err.message,true)}}
async function startCamera(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('Cámara no compatible en este navegador; introduce el EAN manualmente.',true);return}
 try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a']});barcodeStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});
 const video=$('cameraView');video.classList.remove('hidden');video.srcObject=barcodeStream;await video.play();let count=0;const read=async()=>{if(!barcodeStream||!$('cameraView'))return;try{const result=await detector.detect(video);if(result.length){const code=result[0].rawValue;stopCamera();const r=await api('/api/barcodes/'+code);toast(r.found?'Código reconocido: '+r.product.name:'Código leído, sin ficha local');return}}catch{}
 if(++count<240)requestAnimationFrame(read);else{stopCamera();toast('No se detectó un código. Puedes escribirlo manualmente.',true)}};requestAnimationFrame(read)
 }catch(err){stopCamera();toast('No se pudo utilizar la cámara: '+err.message,true)}}
function stopCamera(){if(barcodeStream){barcodeStream.getTracks().forEach(t=>t.stop());barcodeStream=null}}
document.addEventListener('submit',doSubmit);document.addEventListener('click',clickAction);
document.addEventListener('input',e=>{if(e.target.id==='productSearch'){searchProduct=e.target.value;const target=$('productCards');if(target)target.innerHTML=productCards()}if(e.target.id==='storeSearch'){searchStore=e.target.value;const target=$('storesList');if(target)target.innerHTML=listStores()}});
document.addEventListener('change',e=>{if(e.target.id==='catalogBasket')selectedBasketCatalog=Number(e.target.value)});
async function boot(){
 try{
  config=await api('/api/config');
  document.querySelectorAll('.demo-accounts,.login-divider,.demo-footnote').forEach(el=>el.classList.toggle('hidden',!config.demo_mode));
  const registration=$('signupCodeWrap');if(registration)registration.classList.toggle('hidden',!config.signup_code_required);
  const r=await api('/api/auth/session');csrf=r.csrf;sessionReady=true;await refresh(false);applyIncomingInvite();
 }catch(e){showAuth()}
}
boot();

// Poll fallback for Safari/iOS when SSE connections are suspended, with form safety.
let basketSyncInFlight=false;
setInterval(async()=>{
 if(!sessionReady||!state||view!=='baskets'||!basketId||document.visibilityState!=='visible'||basketSyncInFlight)return;
 const active=document.activeElement;
 if(active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName))return;
 basketSyncInFlight=true;
 try{const next=await api('/api/baskets/'+basketId);
 if(basketDetail&&JSON.stringify(next)!==JSON.stringify(basketDetail)){basketDetail=next;render()}}
 catch(err){console.warn('Cesta sin sincronizar:',err.message)}finally{basketSyncInFlight=false}
},10000);
setInterval(async()=>{if(sessionReady&&state&&view==='circle'&&document.visibilityState==='visible'){
 const active=document.activeElement;if(active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName))return;
 try{state.family_tasks=await api('/api/family/tasks');render()}catch(e){console.warn(e.message)}
}},18000);
window.addEventListener('online',()=>{const el=$('netBanner');if(el)el.classList.add('hidden');if(sessionReady)refresh().catch(()=>{})});
window.addEventListener('offline',()=>{const el=$('netBanner');if(el)el.classList.remove('hidden')});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&sessionReady)refresh().catch(()=>{})});
